class Produk {
    String nama;
    int harga;

    Produk(String nama, int harga) {
        this.nama = nama;
        this.harga = harga;
    }

    int hargaAkhir() {
        return harga;
    }
}

class ProdukDiskon extends Produk {
    ProdukDiskon(String nama, int harga) {
        super(nama, harga);
    }

    @Override
    int hargaAkhir() {
        return harga * 90 / 100;
    }
}

