public class Main {
    public static void main(String[] args) {
        Produk[] keranjang = {
            new Produk("Kopi", 15000),
            new ProdukDiskon("Roti", 10000),
            new ProdukPajak("Rokok", 30000)
        };
        for (Produk p : keranjang) {
            System.out.println(p.nama + ": " + p.hargaAkhir());
        }

        int total = 0;
        for (Produk p : keranjang) {
            total += p.hargaAkhir();
        }
        System.out.println("Total: " + total);
    }
}

